      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n9 / 17 ~ 10 / 12 )개인사업자 인터뷰 ( 사업장내 설치 에어컨관련)\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.09.10. 21:01\n조회 47\n구독\n9 / 17 ~ 10 / 12 )개인사업자 인터뷰 ( 사업장내 설치 에어컨관련)\n하기 내용으로 1:1 간단한 인터뷰 진행할 예정이오니 많은 신청 부탁드립니다.\n1. 대상자 조건\n개인 사업자 중 2026년에 매장 내 천장형 에어컨 ( 4개 날개형 ) 또는 중,대형 스탠드 에어컨 신규/교체/추가 설치한 사업주\n매장 오픈 시 업소용 에어컨 구매 및 설치에 직접 관여한 자\n2. 진행 일정\n9 / 17 ~ 10 / 12 사이\n세부 일정은 대상자 선정 후 개별 안내\n3. 진행 장소 및 내용\n사업중이신 사업장으로 내방하여 오프라인으로 약 1시간 동안 간단한 설문/인터뷰 진행\n진행 내용 : 사업장 내 설치된 에어컨 현황 파악 및 설치시 의사결정에 미친 요인등 인터뷰\n4. 사례비\n사례비: 100,000원\n5. 신청 시 기재사항\n성함 / 연락처 /사업장 주소 / 업종 ( ex: 음식점, 카페, 숙박업, 미용업, 헬스장, 약국, 학원, 부동산, 인테리어, 숙박업 , 법무, 회계, 광고 등등) / 사업장 에어컨 설치 년도 / 사업장 에어컨 종류 ( 천장형 or 스탠드형) / 사업장 에어컨 브랜드\nhttps://forms.gle/d2AsPm3sriG1WEFq6\n9 / 17 ~ 10 / 12 )개인사업자 인터뷰 ( 사업장내 설치 에어컨관련)\n010-4648-7146 -- 연락처 사이 하이픈 꼭 챙겨주시구요^^ 하이픈 안챙기시는 분 연락처에 숫자가 한개씩 누락되어서 숫자10개가 옵니다ㅠㅠ 연락처 적으신 후 숫자 11개 모두 적었는지 확인 부탁드립니다^^ 간혹 남의번호 적는분이 계십니다,그사람 아닌데요 하면,굉장히 민망하지요ㅠ 적고나서 확인부탁드립니다~ 해당없는 칸에는 해당없음 또는 점 . 또는 무 로 적어주세요~\nforms.gle\n좋아요\n0\n'좋아요'로 마음을 나누세요!\n송파구의 더 많은 인기글 보러가기\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n첫 댓글을 남겨보세요\n전체글\n9 / 17 ~ 10 / 12 )개인사업자 인터뷰 ( 사업장내 설치 에어컨관련)\n좌담회알바좌담회카페\n26.09.10.\n댓글\n0\n9/16)만25-39세 여성) 9월 식품 맛테스트\n좌담회알바좌담회카페\n26.09.10.\n댓글\n0\n9/17~18) 20~59세 남,여) 주사형 비만 치료제 관련 좌담회\n좌담회알바좌담회카페\n26.09.10.\n댓글\n0\n고유링크) 9/21~23) 3년 이상 인도 거주 경험이 있거나 현재 거주중인 만 40~49세 남녀 한국인 온라인 좌담회\n좌담회알바좌담회카페\n26.09.10.\n댓글\n0\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n목록으로\n좋아요\n0\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
